import importlib.util
import os
from pathlib import Path
import subprocess
import sys

import pytest


@pytest.fixture
def business_path():
    root = Path(os.environ.get("DEMO_WORKSPACE", Path(__file__).parents[1] / "before"))
    path = root.resolve() / "ticket_tool.py"
    assert path.is_file(), f"Missing business module: {path}"
    return path


@pytest.fixture
def run_cli(business_path):
    def run(*args):
        return subprocess.run(
            [sys.executable, str(business_path), *args],
            text=True, capture_output=True, timeout=10, check=False,
        )
    return run


@pytest.fixture
def ticket_module(business_path):
    spec = importlib.util.spec_from_file_location("ticket_acceptance_subject", business_path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

"""BASE-001/BASE-002: immutable pre-existing behavior acceptance tests."""
import json


def ids(result):
    assert result.returncode == 0, result.stderr
    assert result.stderr == ""
    return [ticket["id"] for ticket in json.loads(result.stdout)]


def test_list_all_stable_order(run_cli):
    assert ids(run_cli()) == [1, 2, 3, 4, 5, 6]


def test_list_preserves_data_fields(run_cli):
    result = run_cli()
    assert result.returncode == 0
    assert json.loads(result.stdout)[0] == {
        "id": 1, "title": "Login error", "owner": "alice", "status": "open"
    }


def test_owner_alice(run_cli):
    assert ids(run_cli("--owner", "alice")) == [1, 3, 5]


def test_owner_bob(run_cli):
    assert ids(run_cli("--owner", "bob")) == [2, 4]


def test_unknown_owner(run_cli):
    assert ids(run_cli("--owner", "nobody")) == []


def test_owner_case_sensitive(run_cli):
    assert ids(run_cli("--owner", "ALICE")) == []


def test_empty_owner(run_cli):
    assert ids(run_cli("--owner", "")) == []


def test_function_sorting_and_owner(ticket_module):
    assert [item["id"] for item in ticket_module.list_tickets()] == [1, 2, 3, 4, 5, 6]
    assert [item["id"] for item in ticket_module.list_tickets(owner="alice")] == [1, 3, 5]


def test_repeated_calls_do_not_mutate_results(ticket_module):
    before = ticket_module.list_tickets()
    ticket_module.list_tickets(owner="bob")
    assert ticket_module.list_tickets() == before

"""STATUS-001 and STATUS-002 v2: identical tests before and after MiniMax."""
import json

import pytest


def ids(result):
    assert result.returncode == 0, result.stderr
    assert result.stderr == ""
    return [ticket["id"] for ticket in json.loads(result.stdout)]


@pytest.mark.parametrize("status,expected", [
    ("open", [1, 4]), ("in_progress", [2, 5]), ("closed", [3, 6]),
])
def test_each_valid_status(run_cli, status, expected):
    assert ids(run_cli("--status", status)) == expected


@pytest.mark.parametrize("owner,status,expected", [
    ("alice", "open", [1]), ("alice", "in_progress", [5]),
    ("alice", "closed", [3]), ("bob", "closed", []),
    ("nobody", "open", []),
])
def test_combined_filters(run_cli, owner, status, expected):
    assert ids(run_cli("--owner", owner, "--status", status)) == expected


@pytest.mark.parametrize("status", ["OPEN", "unknown", "", " open", "open "])
def test_invalid_status_is_explicit(run_cli, status):
    result = run_cli("--status", status)
    assert result.returncode == 2
    assert result.stdout == ""
    assert "invalid status" in result.stderr.lower()
    for canonical in ("open", "in_progress", "closed"):
        assert canonical in result.stderr


def test_function_status_and_combination(ticket_module):
    assert [t["id"] for t in ticket_module.list_tickets(status="open")] == [1, 4]
    assert [t["id"] for t in ticket_module.list_tickets(owner="alice", status="open")] == [1]


def test_function_none_preserves_behavior(ticket_module):
    assert ticket_module.list_tickets(status=None) == ticket_module.list_tickets()
    assert ticket_module.list_tickets(owner="alice", status=None) == ticket_module.list_tickets(owner="alice")


@pytest.mark.parametrize("status", ["OPEN", "unknown", "", " open", "open "])
def test_function_invalid_status(ticket_module, status):
    with pytest.raises(ValueError):
        ticket_module.list_tickets(status=status)

